// ALEA — Templates for the bloc code-gen adapter.
//
// Same architectural rules as riverpod_manual/templates.dart: each constant
// is one whole multi-line string; the engine substitutes `{{variable}}`
// placeholders.

const String blocStateTemplate = '''
// Generated by ALEA (bloc). Do not edit by hand.
import 'package:equatable/equatable.dart';

sealed class {{state_class}} extends Equatable {
  const {{state_class}}();
  @override
  List<Object?> get props => const [];
}

final class {{state_class}}Initial extends {{state_class}} {
  const {{state_class}}Initial();
}

final class {{state_class}}Loading extends {{state_class}} {
  const {{state_class}}Loading();
}

final class {{state_class}}Ready extends {{state_class}} {
  final String message;
  const {{state_class}}Ready(this.message);
  @override
  List<Object?> get props => [message];
}

final class {{state_class}}Failed extends {{state_class}} {
  final String error;
  const {{state_class}}Failed(this.error);
  @override
  List<Object?> get props => [error];
}
''';

