const String blocBlocTemplate = '''
// Generated by ALEA (bloc). Do not edit by hand.
import 'package:bloc/bloc.dart';

import '{{state_import}}';
import '{{event_import}}';

class {{bloc_class}} extends Bloc<{{event_class}}, {{state_class}}> {
  {{bloc_class}}() : super(const {{state_class}}Initial()) {
    on<{{event_class}}Start>((event, emit) async {
      emit(const {{state_class}}Loading());
      emit(const {{state_class}}Ready('{{feature_human_name}} ready'));
    });
    on<{{event_class}}Reset>((event, emit) {
      emit(const {{state_class}}Initial());
    });
  }
}
''';

const String blocScreenTemplate = '''
// Generated by ALEA (bloc). Do not edit by hand.
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import '{{bloc_import}}';
import '{{state_import}}';

class {{screen_class}} extends StatelessWidget {
  const {{screen_class}}({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocProvider<{{bloc_class}}>(
      create: (_) => {{bloc_class}}(),
      child: Scaffold(
        appBar: AppBar(title: const Text('{{feature_human_name}}')),
        body: BlocBuilder<{{bloc_class}}, {{state_class}}>(
          builder: (context, state) {
            return Center(
              child: switch (state) {
                {{state_class}}Initial() => const Text('start'),
                {{state_class}}Loading() => const CircularProgressIndicator(),
                {{state_class}}Ready(:final message) => Text(message),
                {{state_class}}Failed(:final error) => Text(error),
              },
            );
          },
        ),
      ),
    );
  }
}
''';
